constexpr uint8_t LED_PIN = LED_BUILTIN;
uint32_t previousMs = 0;
bool ledOn = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  uint32_t now = millis();
  if ((uint32_t)(now - previousMs) >= 500) {
    previousMs = now;
    ledOn = !ledOn;
    digitalWrite(LED_PIN, ledOn);
  }
}
